int main(void) {
  i2c_init(I2C_CLOCK_SPEED_STANDARD);
  ssd1306_init();

  // clear whole display
  ssd1306_fill_gddram(0, SSD1306_N_PAGES, 0, SSD1306_N_COLS, 0);

  // debug led
  DDRB |= (1 << DDB1);
  uint8_t state = 0;

  uint8_t sx = 0;
  uint8_t sy = 0;
  uint8_t c = '0';

  while (1) {
    if (state) {
      PORTB &= ~(1 << PB1);
    } else {
      PORTB |= (1 << PB1);
    }
    state = !state;

    uint32_t idx = FONT_DEJAVUSANS_CIDX(c);
    uint32_t off = pgm_read_dword(FONT_DEJAVUSANS_OFFSETS + idx);
    uint8_t w = pgm_read_byte(FONT_DEJAVUSANS_WIDTHS + idx);
    const uint8_t *fontDataP = FONT_DEJAVUSANS_GBUF + off;
    // handle cursor end of line
    if (sx + w > 128) {
      sy += FONT_DEJAVUSANS_NUM_PAGES;
      sx = 0;
    }
    // handle cursor at bottom right of screen (end)
    if (sy >= 8) {
      // clear display
      ssd1306_fill_gddram(0, SSD1306_N_PAGES, 0, SSD1306_N_COLS, 0);
      sy = 0;
      sx = 0;
    }
    // render glyph
    ssd1306_write_gddram(sy, sy + FONT_DEJAVUSANS_NUM_PAGES, sx, sx + w,
                         fontDataP, w * FONT_DEJAVUSANS_NUM_PAGES, SSD1306_F_PGM);

    // advance cursor
    sx += w;
    // move to next character
    c++;
    if (c > 126) {
      c = 33;
    }

    _delay_ms(DELAY_MS);
  }
}
